#include <stdio.h>
#include <string.h>

int main() {
    char s[100005];
    if (fgets(s, sizeof(s), stdin) == NULL) {
        printf("0\n");
        return 0;
    }
    int len = strlen(s);
    while (len > 0 && (s[len-1] == '\n' || s[len-1] == '\r')) len--;
    int last[256];
    memset(last, -1, sizeof(last));
    int max_len = 0, start = 0;
    for (int i = 0; i < len; i++) {
        unsigned char c = (unsigned char)s[i];
        if (last[c] >= start) start = last[c] + 1;
        else if (i - start + 1 > max_len) max_len = i - start + 1;
        last[c] = i;
    }
    printf("%d\n", max_len);
    return 0;
}
